// Generates src/lib/contract/generated.ts from the backend OpenAPI document and stream event schema.
// Source: argument or CONTRACT_SOURCE, a contract directory or an API base URL. --check: compare only.
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { compile } from "json-schema-to-typescript";

const DEFAULT_SOURCE = "../backend/contract";
const OUTPUT = "src/lib/contract/generated.ts";
const BANNER = [
  "// DO NOT EDIT. Generated by `npm run contract:generate` from backend/contract",
  "// (openapi.json and stream-events.schema.json). The backend is the source of truth.",
].join("\n");

const args = process.argv.slice(2);
const check = args.includes("--check");
const source =
  args.find((a) => !a.startsWith("--")) ?? (process.env.CONTRACT_SOURCE || DEFAULT_SOURCE);

async function load(base, file, urlPath) {
  if (/^https?:\/\//.test(base)) {
    const url = `${base.replace(/\/$/, "")}${urlPath}`;
    const response = await fetch(url, { signal: AbortSignal.timeout(10_000) });
    if (!response.ok) throw new Error(`GET ${url} returned ${response.status}`);
    return response.json();
  }
  return JSON.parse(await readFile(join(base, file), "utf8"));
}

// Pydantic titles every property; without this the generator emits aliases such as Type1 and Text1.
function normalize(node) {
  if (Array.isArray(node)) return node.map(normalize);
  if (node === null || typeof node !== "object") return node;
  const out = Object.fromEntries(Object.entries(node).map(([k, v]) => [k, normalize(v)]));
  if (typeof out.$ref === "string") {
    out.$ref = out.$ref.replace("#/components/schemas/", "#/$defs/");
  }
  if (out.properties) {
    for (const prop of Object.values(out.properties)) delete prop.title;
  }
  return out;
}

const openapi = await load(source, "openapi.json", "/openapi.json");
const stream = await load(source, "stream-events.schema.json", "/schemas/stream-events.json");
// The generator emits every $defs entry only under an object root, so StreamEvent is one entry.
const { $defs, ...streamEvent } = stream;
const schema = normalize({
  title: "Contract",
  type: "object",
  additionalProperties: false,
  $defs: { ...openapi.components?.schemas, ...$defs, StreamEvent: streamEvent },
});
const types = await compile(schema, "Contract", {
  bannerComment: BANNER,
  additionalProperties: false,
  unreachableDefinitions: true,
});

if (check) {
  const committed = await readFile(OUTPUT, "utf8").catch(() => null);
  if (committed?.replaceAll("\r\n", "\n") !== types) {
    console.error(`${OUTPUT} does not match ${source}. Run: npm run contract:generate`);
    process.exit(1);
  }
  console.log(`${OUTPUT} matches ${source}`);
} else {
  await mkdir(dirname(OUTPUT), { recursive: true });
  await writeFile(OUTPUT, types);
  console.log(`wrote ${OUTPUT} from ${source}`);
}
